#!/usr/bin/env python3
"""Generate the embedded LuaSocket script table used by Dora Lua states."""

from pathlib import Path


ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / "LuaScripts.h"
MODULES = (
	("socket", "src/socket.lua"),
	("mime", "src/mime.lua"),
	("ltn12", "src/ltn12.lua"),
	("socket.ftp", "src/ftp.lua"),
	("socket.headers", "src/headers.lua"),
	("socket.http", "src/http.lua"),
	("ssl.https", "src/ssl/https.lua"),
	("socket.smtp", "src/smtp.lua"),
	("socket.tp", "src/tp.lua"),
	("socket.url", "src/url.lua"),
)


def format_bytes(data: bytes) -> str:
	values = [str(value) for value in data]
	return "\n".join(
		"\t" + ", ".join(values[index:index + 24]) + ","
		for index in range(0, len(values), 24)
	)


lines = [
	"// Generated by generate_lua_scripts.py from LuaSocket 3.1.0 sources.",
	"#pragma once",
	"",
	"#include <cstddef>",
	"",
	"namespace DoraLuaSocketScripts {",
	"struct Script {",
	"\tconst char* module;",
	"\tconst char* chunkName;",
	"\tconst unsigned char* data;",
	"\tstd::size_t size;",
	"};",
	"",
]

entries = []
for index, (module, relative_path) in enumerate(MODULES):
	data = (ROOT / relative_path).read_bytes()
	name = f"script_{index}"
	lines.extend((
		f"inline constexpr unsigned char {name}[] = {{",
		format_bytes(data),
		"};",
		"",
	))
	entries.append((module, relative_path, name))

lines.append("inline constexpr Script scripts[] = {")
for module, relative_path, name in entries:
	lines.append(
		f'\t{{"{module}", "@dora-builtin/luasocket/{relative_path}", '
		f"{name}, sizeof({name})}},"
	)
lines.extend(("};", "} // namespace DoraLuaSocketScripts", ""))
OUTPUT.write_text("\n".join(lines), encoding="utf-8")
